// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"id","terms":[["address-poisoning","Address poisoning (peracunan alamat)","Address poisoning adalah penipuan di mana pelaku mengirim transaksi bernilai kecil atau nol dari alamat yang mirip dengan alamat yang sering Anda pakai, berharap Anda menyalin alamat palsu itu dari riwayat transaksi.","wallets-security",1],["airdrop","Airdrop","Airdrop adalah pembagian token gratis oleh sebuah proyek kripto ke alamat dompet tertentu, biasanya untuk pengguna awal, pemegang token tertentu, atau sebagai promosi.","basics",1],["unified-trading-account","Akun trading terpadu (Unified Trading Account)","Akun trading terpadu adalah jenis akun bursa yang menggabungkan saldo spot, margin, futures, dan opsi dalam satu dompet, sehingga satu pool aset bisa dipakai sebagai margin untuk berbagai produk.","exchange-features",1],["active-addresses","Alamat aktif (active addresses)","Alamat aktif adalah jumlah alamat blockchain unik yang mengirim atau menerima transaksi dalam periode tertentu, dipakai sebagai gambaran kasar tingkat penggunaan sebuah jaringan.","onchain",1],["wallet-address","Alamat dompet (wallet address)","Alamat dompet adalah deretan karakter unik yang berfungsi seperti nomor rekening untuk menerima kripto di jaringan blockchain tertentu.","wallets-security",1],["all-time-high","All-time high (ATH)","All-time high (ATH) adalah harga tertinggi yang pernah dicapai sebuah aset sejak mulai diperdagangkan.","basics",1],["altcoin","Altcoin","Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan.","basics",1],["aml","AML (anti pencucian uang)","AML adalah kumpulan aturan dan prosedur untuk mencegah dana hasil kejahatan dicuci lewat sistem keuangan, termasuk lewat bursa dan transfer aset kripto.","regulation",1],["amm","AMM (automated market maker)","AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain.","defi",1],["on-chain-analysis","Analisis on-chain","Analisis on-chain adalah cara membaca data transaksi yang tercatat di blockchain, seperti aliran dana ke bursa, aktivitas alamat, dan pergerakan whale, untuk memahami perilaku pelaku pasar.","onchain",1],["apr-vs-apy","APR vs APY","APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama.","defi",1],["arbitrage","Arbitrase (arbitrage)","Arbitrase adalah strategi memanfaatkan selisih harga aset yang sama di dua pasar berbeda, misalnya membeli di exchange yang lebih murah dan menjual di exchange yang lebih mahal secara bersamaan.","trading",1],["funding-rate-arbitrage","Arbitrase funding rate (funding rate arbitrage)","Arbitrase funding rate adalah strategi netral pasar yang membeli aset di spot dan membuka short dengan ukuran sama di perpetual, sehingga risiko harga saling meniadakan dan keuntungan berasal dari pembayaran funding.","derivatives",1],["exchange-netflow","Arus masuk dan keluar bursa (exchange netflow)","Exchange netflow adalah selisih antara jumlah kripto yang masuk ke dompet bursa dan yang keluar dari bursa dalam periode tertentu, dipakai untuk membaca niat jual atau simpan para pemegang.","onchain",1],["two-factor-authentication","Autentikasi dua faktor (2FA)","Autentikasi dua faktor (2FA) adalah lapisan keamanan yang meminta bukti kedua selain kata sandi, misalnya kode dari aplikasi autentikator atau kunci keamanan fisik, sebelum Anda bisa login atau menarik dana.","wallets-security",1],["auto-deleveraging","Auto-deleveraging (ADL)","Auto-deleveraging adalah mekanisme darurat exchange futures yang otomatis menutup sebagian posisi trader yang sedang untung untuk menutup kerugian dari posisi bangkrut, ketika insurance fund tidak cukup.","derivatives",1],["futures-basis","Basis futures (futures basis)","Basis futures adalah selisih antara harga kontrak futures dan harga spot aset yang sama, biasanya dinyatakan dalam persen atau persen per tahun.","derivatives",1],["bear-market","Bear market (pasar bearish)","Bear market adalah periode ketika harga aset di pasar cenderung turun secara berkelanjutan, biasanya 20% atau lebih dari puncaknya, disertai sentimen pesimis dan volume yang menurun.","basics",1],["maker-taker-fees","Biaya maker dan taker (maker-taker fee)","Biaya maker dan taker adalah dua tarif biaya trading di exchange: maker dikenakan pada order yang menambah likuiditas ke order book, sedangkan taker dikenakan pada order yang langsung mengambil likuiditas yang sudah ada.","trading",1],["withdrawal-fee","Biaya penarikan (withdrawal fee)","Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan.","exchange-features",1],["bid-ask-spread","Bid-ask spread (spread)","Bid-ask spread adalah selisih antara harga beli tertinggi (bid) dan harga jual terendah (ask) di order book pada satu waktu.","trading",1],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin.","basics",1],["bitcoin-halving","Bitcoin halving","Bitcoin halving adalah peristiwa terjadwal kira-kira setiap empat tahun, atau tepatnya setiap 210.000 blok, ketika imbalan blok untuk penambang dipotong setengah.","basics",1],["block-explorer","Block explorer","Block explorer adalah situs atau aplikasi untuk mencari dan melihat data blockchain secara publik, seperti status transaksi, saldo alamat, isi blok, dan jumlah konfirmasi.","onchain",1],["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat.","basics",1],["bull-market","Bull market (pasar bullish)","Bull market adalah periode ketika harga aset di pasar cenderung naik secara berkelanjutan selama berminggu-minggu hingga bertahun-tahun, disertai sentimen optimis dan minat beli yang tinggi.","basics",1],["no-kyc-exchange","Bursa tanpa KYC (no-KYC exchange)","Bursa tanpa KYC adalah platform yang mengizinkan Anda berdagang atau menarik kripto tanpa verifikasi identitas, biasanya dengan batas penarikan tertentu atau sebagai bursa terdesentralisasi.","regulation",1],["cbdc","CBDC (mata uang digital bank sentral)","CBDC adalah bentuk digital dari mata uang resmi suatu negara yang diterbitkan dan dijamin langsung oleh bank sentral, misalnya rupiah digital yang sedang dikaji Bank Indonesia.","stablecoins",1],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC.","trading",1],["circulating-supply","Circulating supply (suplai beredar)","Circulating supply adalah jumlah koin atau token yang saat ini benar-benar beredar dan bisa diperdagangkan di pasar, tidak termasuk yang masih terkunci atau belum diterbitkan.","basics",1],["coin-vs-token","Coin vs token","Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract.","basics",1],["cold-wallet","Cold wallet (cold storage)","Cold wallet adalah cara menyimpan kripto dengan private key yang dibuat dan disimpan sepenuhnya offline, sehingga tidak bisa dijangkau peretas lewat internet.","wallets-security",1],["instant-convert","Convert (tukar instan)","Convert adalah fitur bursa untuk menukar satu aset kripto ke aset lain secara instan dengan harga yang dikunci beberapa detik, tanpa perlu memasang order di order book.","exchange-features",1],["copy-trading","Copy trading","Copy trading adalah fitur bursa yang otomatis meniru posisi trader lain, yang biasa disebut lead trader, ke akun Anda sesuai modal dan pengaturan yang Anda pilih.","exchange-features",1],["cross-chain-bridge","Cross-chain bridge (jembatan antar-chain)","Cross-chain bridge adalah protokol yang memindahkan aset atau data dari satu blockchain ke blockchain lain, misalnya memindahkan USDC dari Ethereum ke Arbitrum.","defi",1],["crypto-earn","Crypto Earn (produk simpanan kripto)","Crypto Earn adalah kategori produk di bursa yang memberi imbal hasil atas aset kripto yang Anda simpan, misalnya simpanan fleksibel, simpanan berjangka, staking, atau produk terstruktur.","exchange-features",1],["cryptocurrency","Cryptocurrency (aset kripto)","Cryptocurrency atau aset kripto adalah aset digital yang dicatat di blockchain dan diamankan dengan kriptografi, sehingga bisa dikirim antarpengguna tanpa bank sebagai perantara.","basics",1],["dao","DAO (organisasi otonom terdesentralisasi)","DAO adalah organisasi yang aturan dan keputusannya dijalankan lewat smart contract dan voting anggota, biasanya pemegang governance token, bukan melalui struktur manajemen tradisional.","defi",1],["defi","DeFi (keuangan terdesentralisasi)","DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat.","defi",1],["defi-lending","DeFi lending (pinjam-meminjam DeFi)","DeFi lending adalah layanan pinjam-meminjam kripto lewat smart contract, di mana pemberi pinjaman mendapat bunga dan peminjam harus menyetor jaminan melebihi nilai pinjamannya.","defi",1],["delisting","Delisting","Delisting adalah keputusan bursa untuk menghapus token atau pasangan perdagangan dari platformnya, sehingga perdagangan dihentikan dan pengguna diberi batas waktu untuk menarik aset.","exchange-features",1],["demo-trading","Demo trading (akun demo)","Demo trading adalah mode latihan di bursa yang memakai saldo virtual, sehingga Anda bisa mencoba spot, futures, leverage, atau bot dengan harga pasar nyata tanpa mempertaruhkan uang sungguhan.","exchange-features",1],["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS.","stablecoins",1],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara.","defi",1],["synthetic-dollar","Dolar sintetis (synthetic dollar)","Dolar sintetis adalah token bernilai sekitar 1 dolar yang dijaga lewat posisi delta-netral, yaitu memegang aset kripto sekaligus membuka posisi short dengan ukuran sama di kontrak berjangka perpetual.","stablecoins",1],["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) adalah strategi membeli aset dengan nominal tetap secara berkala, misalnya setiap minggu atau bulan, tanpa memedulikan harga saat itu.","trading",1],["crypto-wallet","Dompet kripto (crypto wallet)","Dompet kripto adalah aplikasi, perangkat, atau layanan yang menyimpan kunci untuk mengakses aset kripto Anda di blockchain dan memungkinkan Anda menerima, mengirim, serta menandatangani transaksi.","wallets-security",1],["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri.","wallets-security",1],["multisig-wallet","Dompet multisig (multi-signature)","Dompet multisig adalah dompet yang membutuhkan beberapa tanda tangan dari kunci berbeda, misalnya 2 dari 3, sebelum sebuah transaksi bisa dijalankan.","wallets-security",1],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda.","wallets-security",1],["dual-investment","Dual investment (investasi ganda)","Dual investment adalah produk terstruktur bursa yang memberi imbal hasil tinggi, tetapi saat jatuh tempo Anda bisa menerima aset yang berbeda dari yang disetor, tergantung harga terhadap target.","exchange-features",1],["tokenized-gold","Emas tokenisasi (tokenized gold)","Emas tokenisasi adalah token blockchain yang setiap unitnya didukung sejumlah emas fisik yang disimpan kustodian, misalnya PAXG dan XAUT yang masing-masing mewakili satu troy ounce emas.","tokenized-assets",1],["spot-bitcoin-etf","ETF Bitcoin spot","ETF Bitcoin spot adalah reksa dana yang diperdagangkan di bursa saham dan memegang bitcoin asli sebagai aset dasarnya, sehingga harga sahamnya mengikuti harga BTC.","regulation",1],["ethereum","Ethereum (ETH)","Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking.","basics",1],["fear-and-greed-index","Fear and Greed Index (indeks ketakutan dan keserakahan)","Fear and Greed Index adalah indikator sentimen pasar kripto berskala 0 sampai 100, di mana angka rendah menunjukkan ketakutan ekstrem dan angka tinggi menunjukkan keserakahan ekstrem.","onchain",1],["fiat-on-ramp","Fiat on-ramp","Fiat on-ramp adalah layanan atau jalur untuk menukar uang biasa seperti rupiah menjadi aset kripto, misalnya lewat transfer bank, kartu, e-wallet, atau P2P di bursa.","regulation",1],["flash-loan","Flash loan (pinjaman kilat)","Flash loan adalah pinjaman tanpa jaminan di DeFi yang harus dipinjam dan dikembalikan dalam satu transaksi yang sama; jika tidak dilunasi, seluruh transaksi dibatalkan otomatis.","defi",1],["fomo","FOMO (fear of missing out)","FOMO atau fear of missing out adalah rasa takut ketinggalan keuntungan yang mendorong trader membeli secara impulsif setelah harga sudah naik tajam.","basics",1],["fud","FUD (fear, uncertainty, doubt)","FUD adalah singkatan dari fear, uncertainty, and doubt, yaitu informasi atau rumor negatif yang menimbulkan rasa takut dan ragu sehingga mendorong orang menjual aset.","basics",1],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) adalah perkiraan nilai sebuah proyek kripto jika seluruh suplai maksimal tokennya sudah beredar, dihitung dari harga saat ini dikali suplai maksimal atau total.","basics",1],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot.","derivatives",1],["delivery-futures","Futures berjangka (delivery futures)","Futures berjangka atau delivery futures adalah kontrak futures dengan tanggal jatuh tempo tetap, misalnya mingguan atau kuartalan, yang diselesaikan pada harga settlement di tanggal tersebut.","derivatives",1],["coin-margined-futures","Futures coin-margined (inverse futures)","Futures coin-margined adalah kontrak futures yang memakai koin kripto seperti BTC sebagai margin dan mata uang penyelesaian, sehingga untung dan rugi Anda dihitung dalam koin tersebut, bukan dalam USDT.","derivatives",1],["usdt-margined-futures","Futures USDT-margined (linear futures)","Futures USDT-margined adalah kontrak futures yang memakai stablecoin USDT sebagai margin dan mata uang penyelesaian, sehingga untung dan rugi dihitung langsung dalam USDT secara linear.","derivatives",1],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut.","basics",1],["governance-token","Governance token (token tata kelola)","Governance token adalah token yang memberi pemegangnya hak suara atas keputusan sebuah protokol atau DAO, seperti perubahan parameter, penggunaan kas, atau peningkatan kontrak.","defi",1],["candlestick-chart","Grafik candlestick (candle)","Grafik candlestick adalah grafik harga yang menampilkan harga pembukaan, tertinggi, terendah, dan penutupan (OHLC) untuk setiap periode dalam bentuk batang menyerupai lilin.","trading",1],["grid-trading-bot","Grid trading bot (bot grid)","Grid trading bot adalah bot otomatis yang memasang serangkaian order beli dan jual di beberapa tingkat harga dalam satu rentang, untuk mengambil untung kecil berulang saat harga naik turun.","exchange-features",1],["hardware-wallet","Hardware wallet (dompet perangkat keras)","Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel.","wallets-security",1],["index-price","Harga indeks (index price)","Harga indeks adalah rata-rata tertimbang harga spot sebuah aset dari beberapa exchange besar, dipakai exchange sebagai acuan untuk mark price, funding rate, dan settlement kontrak futures.","derivatives",1],["liquidation-price","Harga likuidasi (liquidation price)","Harga likuidasi adalah perkiraan harga mark price di mana posisi leverage Anda akan ditutup paksa karena margin yang tersisa turun ke level maintenance margin.","derivatives",1],["last-price","Harga terakhir (last traded price)","Harga terakhir adalah harga transaksi paling akhir yang benar-benar terjadi di order book sebuah exchange, dan biasanya inilah angka yang Anda lihat di grafik dan daftar pasar.","derivatives",1],["hash-rate","Hash rate","Hash rate adalah total daya komputasi yang dipakai penambang untuk mengamankan blockchain proof of work seperti Bitcoin, diukur dalam jumlah tebakan hash per detik.","onchain",1],["hedging","Hedging (lindung nilai)","Hedging adalah strategi membuka posisi yang berlawanan dengan aset atau posisi yang Anda pegang untuk mengurangi risiko kerugian akibat pergerakan harga, dengan konsekuensi potensi untungnya ikut berkurang.","derivatives",1],["hodl","HODL","HODL adalah istilah kripto untuk strategi menyimpan aset dalam jangka panjang tanpa terpengaruh naik turunnya harga harian.","basics",1],["hot-wallet","Hot wallet (dompet panas)","Hot wallet adalah dompet kripto yang private key-nya disimpan di perangkat yang terhubung ke internet, seperti aplikasi ponsel atau ekstensi browser, sehingga praktis untuk transaksi harian.","wallets-security",1],["impermanent-loss","Impermanent loss (kerugian tidak permanen)","Impermanent loss adalah selisih nilai antara menyetor token ke liquidity pool dan sekadar menyimpannya di dompet, yang muncul ketika harga kedua token di pool bergerak berbeda.","defi",1],["insurance-fund","Insurance fund (dana asuransi)","Insurance fund adalah cadangan dana milik exchange futures yang dipakai untuk menutup kerugian ketika posisi yang dilikuidasi ditutup di harga lebih buruk dari harga kebangkrutannya, sehingga trader lain tidak ikut menanggung.","derivatives",1],["blockchain-network","Jaringan deposit (pilihan chain)","Jaringan deposit adalah blockchain yang Anda pilih untuk mengirim atau menerima sebuah aset, misalnya USDT lewat Tron, Ethereum, atau BNB Smart Chain, dan pilihan ini harus sama di sisi pengirim dan penerima.","wallets-security",1],["anti-phishing-code","Kode anti-phishing","Kode anti-phishing adalah kata atau kode rahasia yang Anda tetapkan di akun exchange, lalu dicantumkan di setiap email resmi exchange agar Anda bisa membedakannya dari email palsu.","wallets-security",1],["referral-code","Kode referral (rebate biaya)","Kode referral adalah kode undangan yang Anda masukkan saat mendaftar di bursa kripto, yang dapat memberi Anda potongan atau pengembalian sebagian biaya trading (rebate) sesuai program bursa tersebut.","exchange-features",1],["block-confirmations","Konfirmasi blok (block confirmations)","Konfirmasi blok adalah jumlah blok yang sudah ditambahkan sejak transaksi Anda masuk ke blockchain, dan semakin banyak konfirmasi berarti semakin kecil kemungkinan transaksi itu dibatalkan.","wallets-security",1],["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short.","derivatives",1],["futures-contract","Kontrak futures (kontrak berjangka)","Kontrak futures adalah perjanjian untuk membeli atau menjual aset pada harga yang disepakati, sehingga Anda bisa mengambil posisi naik (long) atau turun (short) tanpa harus memegang asetnya langsung.","derivatives",1],["kyc","KYC (Know Your Customer)","KYC adalah proses verifikasi identitas yang wajib dilakukan bursa kripto dan lembaga keuangan, misalnya dengan KTP, foto wajah, dan data alamat, sebelum Anda bisa memakai layanan penuh.","regulation",1],["launchpad","Launchpad (penjualan token)","Launchpad adalah platform penjualan token proyek baru sebelum diperdagangkan di bursa, di mana Anda membeli token dengan harga tetap memakai aset seperti USDT atau token bursa.","exchange-features",1],["launchpool","Launchpool","Launchpool adalah fitur bursa yang memberi Anda token proyek baru secara gratis sebagai imbalan karena mengunci aset tertentu, seperti BNB atau stablecoin, selama periode singkat.","exchange-features",1],["layer-1","Layer 1 (L1)","Layer 1 (L1) adalah blockchain dasar yang memproses dan memfinalisasi transaksinya sendiri dengan mekanisme konsensus dan koin aslinya, seperti Bitcoin, Ethereum, dan Solana.","basics",1],["layer-2","Layer 2 (L2)","Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah.","basics",1],["vip-tier","Level VIP (tingkat biaya VIP)","Level VIP adalah tingkatan biaya trading di bursa kripto yang ditentukan oleh volume perdagangan 30 hari, saldo aset, atau kepemilikan token bursa, di mana level lebih tinggi mendapat biaya maker dan taker lebih rendah.","exchange-features",1],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT.","derivatives",1],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang.","derivatives",1],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan.","trading",1],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi.","trading",1],["liquid-staking","Liquid staking","Liquid staking adalah cara staking di mana Anda menerima token pengganti, seperti stETH dari Lido, yang mewakili koin yang di-stake beserta reward-nya dan tetap bisa diperdagangkan atau dipakai di DeFi.","defi",1],["liquidity-pool","Liquidity pool (kolam likuiditas)","Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi.","defi",1],["token-listing","Listing token","Listing token adalah proses ketika bursa menambahkan token baru ke daftar aset yang bisa disetor dan diperdagangkan, biasanya diumumkan lebih dulu beserta jadwal pembukaan setoran dan perdagangan.","exchange-features",1],["maintenance-margin","Maintenance margin (margin pemeliharaan)","Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda.","derivatives",1],["initial-margin","Margin awal (initial margin)","Margin awal adalah jumlah jaminan minimum yang harus Anda setor untuk membuka posisi dengan leverage, biasanya sama dengan nilai posisi dibagi leverage yang dipilih.","derivatives",1],["margin-call","Margin call","Margin call adalah peringatan bahwa jaminan di akun atau posisi Anda sudah mendekati batas minimum, sehingga Anda perlu menambah margin atau mengurangi posisi agar tidak dilikuidasi.","derivatives",1],["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan.","derivatives",1],["isolated-margin","Margin terisolasi (isolated margin)","Margin terisolasi adalah mode margin di mana setiap posisi punya jaminan sendiri yang terpisah, sehingga jika posisi itu dilikuidasi, kerugiannya hanya terbatas pada margin yang dialokasikan ke posisi tersebut.","derivatives",1],["margin-trading","Margin trading","Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam.","derivatives",1],["mark-price","Mark price (harga tanda)","Mark price adalah harga acuan yang dihitung exchange dari harga indeks beberapa exchange spot dan basis kontrak, dipakai untuk menghitung unrealized PnL dan memicu likuidasi pada kontrak futures.","derivatives",1],["market-capitalization","Market capitalization (kapitalisasi pasar)","Market capitalization atau kapitalisasi pasar adalah nilai total sebuah aset kripto yang beredar, dihitung dari harga saat ini dikali jumlah suplai yang beredar.","basics",1],["market-maker","Market maker","Market maker adalah pihak yang terus-menerus memasang order beli dan jual di dekat harga pasar sehingga trader lain selalu punya lawan transaksi, dan ia mendapat keuntungan dari selisih spread.","trading",1],["market-order","Market order","Market order adalah perintah membeli atau menjual segera di harga terbaik yang tersedia saat itu, sehingga eksekusinya cepat tetapi harga akhirnya tidak dijamin.","trading",1],["memecoin","Memecoin (koin meme)","Memecoin adalah aset kripto yang nilainya terutama digerakkan oleh budaya internet, komunitas, dan tren media sosial, bukan oleh kegunaan teknis atau pendapatan proyek.","basics",1],["memo-tag","Memo / destination tag","Memo atau destination tag adalah kode tambahan selain alamat yang dipakai beberapa jaringan, seperti XRP, Stellar, TON, atau Cosmos, untuk menandai akun penerima di dalam satu alamat bersama milik exchange.","wallets-security",1],["mempool","Mempool","Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator.","onchain",1],["mev","MEV (maximal extractable value)","MEV adalah keuntungan tambahan yang bisa diambil oleh pihak yang mengatur urutan transaksi dalam sebuah blok, misalnya dengan mendahului atau mengapit transaksi pengguna lain.","defi",1],["mica","MiCA (regulasi aset kripto Uni Eropa)","MiCA adalah regulasi Uni Eropa tentang pasar aset kripto yang mengatur penerbit stablecoin dan penyedia jasa aset kripto (CASP) dengan satu set aturan untuk semua negara anggota.","regulation",1],["mining","Mining (penambangan kripto)","Mining atau penambangan kripto adalah proses memakai daya komputasi untuk memvalidasi transaksi dan menambahkan blok baru pada blockchain proof of work, dengan imbalan koin baru dan biaya transaksi.","basics",1],["nft","NFT (non-fungible token)","NFT adalah token unik di blockchain yang mewakili kepemilikan atas satu item digital tertentu, seperti karya seni, koleksi, tiket, atau item game, sehingga tidak bisa ditukar satu banding satu dengan token lain.","defi",1],["node","Node","Node adalah komputer yang menjalankan perangkat lunak blockchain, menyimpan salinan data, memeriksa transaksi dan blok sesuai aturan, lalu meneruskannya ke node lain di jaringan.","onchain",1],["tokenized-treasuries","Obligasi pemerintah tokenisasi (tokenized treasuries)","Obligasi pemerintah tokenisasi adalah token blockchain yang didukung surat utang pemerintah, umumnya US Treasury bills jangka pendek, sehingga pemegangnya mendapat imbal hasil mirip bunga obligasi.","tokenized-assets",1],["oco-order","OCO order (one cancels the other)","OCO order adalah pasangan dua order, biasanya take profit dan stop loss, di mana ketika salah satunya tereksekusi, order lainnya otomatis dibatalkan.","trading",1],["open-interest","Open interest (OI)","Open interest adalah total nilai atau jumlah kontrak futures dan opsi yang masih terbuka dan belum ditutup atau diselesaikan pada suatu waktu.","derivatives",1],["options","Opsi kripto (crypto options)","Opsi kripto adalah kontrak yang memberi pembelinya hak, tetapi bukan kewajiban, untuk membeli (call) atau menjual (put) aset kripto pada harga tertentu (strike) sampai atau pada tanggal jatuh tempo, dengan membayar premi.","derivatives",1],["oracle","Oracle blockchain","Oracle blockchain adalah layanan yang membawa data dari luar blockchain, seperti harga aset, ke dalam smart contract agar kontrak bisa mengambil keputusan berdasarkan data tersebut.","defi",1],["order-book","Order book (buku order)","Order book adalah daftar real-time semua order beli dan order jual yang menunggu di sebuah pasangan perdagangan, disusun berdasarkan harga dan jumlahnya.","trading",1],["p2p-trading","P2P trading (jual beli P2P)","P2P trading adalah jual beli kripto langsung antarpengguna di platform bursa, di mana pembayaran rupiah dilakukan lewat transfer bank atau e-wallet dan kripto penjual ditahan sistem escrow.","exchange-features",1],["geo-restrictions","Pembatasan wilayah (geo-restrictions)","Pembatasan wilayah adalah aturan bursa kripto yang melarang atau membatasi layanan bagi pengguna dari negara tertentu karena alasan regulasi, izin, atau sanksi internasional.","regulation",1],["pig-butchering-scam","Penipuan pig butchering","Pig butchering adalah penipuan jangka panjang di mana pelaku membangun hubungan pertemanan atau asmara dengan korban, lalu membujuknya berinvestasi kripto di platform palsu sampai seluruh dana diambil.","wallets-security",1],["perp-dex","Perp DEX (perpetual on-chain)","Perp DEX adalah decentralized exchange yang menyediakan kontrak berjangka perpetual dengan leverage, di mana margin dan penyelesaian posisi dikelola smart contract atau blockchain, bukan oleh exchange terpusat.","defi",1],["stock-perpetuals","Perpetual saham (stock perpetuals)","Perpetual saham adalah kontrak berjangka perpetual tanpa tanggal jatuh tempo yang mengikuti harga saham atau indeks saham, diperdagangkan dengan margin dan leverage di bursa kripto atau perp DEX.","tokenized-assets",1],["phishing","Phishing (penipuan pancingan)","Phishing adalah penipuan yang meniru pihak tepercaya, seperti exchange, dompet, atau proyek kripto, untuk memancing Anda menyerahkan kata sandi, kode 2FA, seed phrase, atau menandatangani transaksi berbahaya.","wallets-security",1],["portfolio-margin","Portfolio margin","Portfolio margin adalah mode margin yang menghitung kebutuhan jaminan berdasarkan risiko gabungan seluruh portofolio, sehingga posisi yang saling mengimbangi bisa membutuhkan margin jauh lebih kecil.","derivatives",1],["long-and-short","Posisi long dan short","Posisi long adalah posisi yang untung saat harga naik, sedangkan posisi short adalah posisi yang untung saat harga turun; keduanya bisa dibuka di futures maupun margin trading.","derivatives",1],["position-sizing","Position sizing (ukuran posisi)","Position sizing adalah cara menentukan berapa besar modal yang dipakai untuk satu trade, berdasarkan seberapa banyak kerugian yang siap Anda tanggung jika stop loss tersentuh.","trading",1],["post-only-order","Post-only order","Post-only order adalah limit order yang hanya boleh masuk ke order book sebagai order maker, dan otomatis dibatalkan atau disesuaikan jika akan langsung tereksekusi sebagai taker.","trading",1],["private-key","Private key (kunci privat)","Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu.","wallets-security",1],["proof-of-reserves","Proof of reserves (bukti cadangan)","Proof of reserves adalah cara exchange membuktikan bahwa aset yang dipegangnya setidaknya sama dengan saldo yang dimiliki pengguna, biasanya dengan menunjukkan alamat dompet dan bukti Merkle tree.","wallets-security",1],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) adalah mekanisme konsensus di mana validator mengunci koin sebagai jaminan untuk berhak memvalidasi blok, lalu mendapat imbalan atau kena penalti sesuai perilakunya.","basics",1],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) adalah mekanisme konsensus di mana penambang bersaing memecahkan teka-teki komputasi agar berhak menambahkan blok baru dan menerima imbalan.","basics",1],["public-key","Public key (kunci publik)","Public key adalah kunci yang dihitung dari private key dan boleh diketahui orang lain, dipakai jaringan untuk memverifikasi tanda tangan transaksi serta menjadi dasar pembuatan alamat dompet.","wallets-security",1],["long-short-ratio","Rasio long/short (long/short ratio)","Rasio long/short adalah perbandingan antara jumlah akun atau nilai posisi long dan short di pasar futures, dipakai untuk membaca sentimen trader terhadap sebuah aset.","derivatives",1],["risk-reward-ratio","Rasio risk-reward (risk-reward ratio)","Rasio risk-reward adalah perbandingan antara potensi kerugian sebuah trade (jarak ke stop loss) dan potensi keuntungannya (jarak ke take profit), misalnya 1:2.","trading",1],["real-world-assets","Real World Assets (RWA, aset dunia nyata)","Real World Assets (RWA) adalah aset dari dunia keuangan nyata, seperti surat utang negara, kredit, properti, emas, atau saham, yang kepemilikannya direpresentasikan sebagai token di blockchain.","tokenized-assets",1],["reduce-only-order","Reduce-only order","Reduce-only order adalah opsi order di futures yang memastikan order hanya bisa mengurangi atau menutup posisi yang sudah ada, dan tidak akan pernah membuka posisi baru atau menambah posisi ke arah sebaliknya.","derivatives",1],["restaking","Restaking","Restaking adalah memakai kembali ETH atau token liquid staking yang sudah di-stake untuk ikut mengamankan layanan lain, dengan imbalan reward tambahan sekaligus risiko slashing tambahan.","defi",1],["rug-pull","Rug pull","Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar.","wallets-security",1],["tokenized-stocks","Saham tokenisasi (tokenized stocks)","Saham tokenisasi adalah token di blockchain yang mewakili atau mengikuti harga saham nyata, seperti saham perusahaan AS, sehingga bisa diperdagangkan di platform kripto, sering 24 jam.","tokenized-assets",1],["satoshi","Satoshi (sats)","Satoshi atau sats adalah satuan terkecil Bitcoin, di mana 1 BTC sama dengan 100.000.000 satoshi.","basics",1],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang.","wallets-security",1],["short-selling","Short selling (jual short)","Short selling adalah strategi mendapat untung dari penurunan harga dengan menjual aset lebih dulu, lalu membelinya kembali di harga lebih rendah untuk menutup posisi.","derivatives",1],["short-squeeze","Short squeeze","Short squeeze adalah kenaikan harga yang cepat dan tajam karena banyak trader short terpaksa menutup posisi dengan membeli kembali aset, baik karena stop loss maupun likuidasi, sehingga mendorong harga naik lebih jauh.","derivatives",1],["slippage","Slippage","Slippage adalah selisih antara harga yang Anda harapkan saat mengirim order dan harga rata-rata yang benar-benar Anda dapatkan ketika order dieksekusi.","trading",1],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara.","basics",1],["spot-trading","Spot trading (perdagangan spot)","Spot trading adalah jual beli aset kripto secara langsung di harga pasar saat ini, di mana aset benar-benar berpindah ke akun Anda setelah transaksi selesai.","trading",1],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto.","stablecoins",1],["algorithmic-stablecoin","Stablecoin algoritmik (algorithmic stablecoin)","Stablecoin algoritmik adalah stablecoin yang mencoba menjaga patokan harga lewat aturan kode dan insentif pasar, bukan lewat cadangan kas penuh atau jaminan berlebih.","stablecoins",1],["crypto-backed-stablecoin","Stablecoin berjaminan kripto (crypto-backed stablecoin)","Stablecoin berjaminan kripto adalah stablecoin yang dicetak dengan mengunci aset kripto seperti ETH sebagai jaminan dengan nilai lebih besar daripada stablecoin yang diterbitkan.","stablecoins",1],["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama.","defi",1],["stop-limit-order","Stop limit order","Stop limit order adalah order yang aktif saat harga menyentuh harga stop, lalu otomatis memasang limit order di harga limit yang Anda tentukan.","trading",1],["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana.","trading",1],["sub-account","Sub-akun (sub-account)","Sub-akun adalah akun tambahan di bawah akun utama bursa yang punya saldo, posisi, dan API key terpisah, sehingga Anda bisa memisahkan strategi atau dana tanpa membuat akun baru dengan KYC lain.","exchange-features",1],["support-and-resistance","Support dan resistance","Support dan resistance adalah area harga di mana penurunan cenderung tertahan karena banyak pembeli (support) atau kenaikan cenderung tertahan karena banyak penjual (resistance).","trading",1],["take-profit","Take profit","Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan.","trading",1],["time-in-force","Time in force (GTC, IOC, FOK)","Time in force adalah pengaturan yang menentukan berapa lama sebuah order tetap aktif dan bagaimana order diperlakukan jika tidak bisa langsung terisi penuh, dengan opsi umum GTC, IOC, dan FOK.","trading",1],["token-approval","Token approval (izin token)","Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui.","wallets-security",1],["token-burn","Token burn","Token burn adalah penghapusan permanen sejumlah token dari peredaran dengan mengirimnya ke alamat yang tidak bisa diakses siapa pun, sehingga total suplai berkurang.","basics",1],["token-unlock","Token unlock","Token unlock adalah saat sejumlah token yang sebelumnya terkunci, misalnya milik tim atau investor awal, dibuka sesuai jadwal vesting sehingga bisa dipindahkan atau dijual.","basics",1],["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai.","basics",1],["trading-pair","Trading pair (pasangan perdagangan)","Trading pair adalah dua aset yang diperdagangkan satu sama lain di exchange, seperti BTC/USDT, di mana harga aset pertama dinyatakan dalam satuan aset kedua.","trading",1],["trailing-stop","Trailing stop","Trailing stop adalah stop order yang otomatis mengikuti harga ketika bergerak menguntungkan Anda dengan jarak tetap, lalu menutup posisi ketika harga berbalik sejauh jarak itu.","trading",1],["transaction-hash","Transaction hash (TxID)","Transaction hash atau TxID adalah kode unik untuk setiap transaksi di blockchain, yang bisa Anda pakai untuk melacak status transfer di block explorer.","wallets-security",1],["travel-rule","Travel rule","Travel rule adalah aturan yang mewajibkan penyedia jasa aset kripto mengirim dan menerima data pengirim serta penerima bersama transfer kripto, mengikuti Rekomendasi 16 FATF.","regulation",1],["total-value-locked","TVL (total value locked)","TVL adalah total nilai aset kripto yang disetor ke sebuah protokol DeFi atau blockchain, dihitung dalam dolar AS, dan sering dipakai sebagai ukuran kasar seberapa besar sebuah protokol dipakai.","defi",1],["unrealized-pnl","Unrealized PnL (laba/rugi belum terealisasi)","Unrealized PnL adalah keuntungan atau kerugian di atas kertas dari posisi yang masih terbuka, dihitung dari selisih harga masuk dan harga acuan saat ini, dan baru menjadi nyata setelah posisi ditutup.","derivatives",1],["usdc","USDC (USD Coin)","USDC adalah stablecoin yang diterbitkan Circle dan dirancang bernilai 1 dolar AS, didukung cadangan kas dan surat utang pemerintah AS jangka pendek, serta banyak dipakai di DeFi dan exchange.","stablecoins",1],["usdt","USDT (Tether)","USDT adalah stablecoin yang diterbitkan Tether dan dirancang bernilai 1 dolar AS, serta menjadi stablecoin dengan peredaran terbesar dan pasangan perdagangan paling umum di exchange kripto.","stablecoins",1],["validator","Validator","Validator adalah peserta jaringan proof of stake yang mengunci koin sebagai jaminan dan menjalankan software untuk mengusulkan serta mengesahkan blok baru.","basics",1],["vasp","VASP (penyedia jasa aset virtual)","VASP adalah istilah FATF untuk perusahaan yang menyediakan jasa aset kripto bagi orang lain, seperti bursa, penyedia kustodi, dan layanan transfer, yang wajib mematuhi aturan AML dan KYC.","regulation",1],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu.","basics",1],["trading-volume","Volume trading (trading volume)","Volume trading adalah total nilai atau jumlah aset yang diperdagangkan dalam periode tertentu, misalnya 24 jam, dan dipakai untuk mengukur seberapa aktif sebuah pasar.","trading",1],["wash-trading","Wash trading","Wash trading adalah praktik membeli dan menjual aset kepada diri sendiri atau pihak yang bekerja sama untuk menciptakan kesan volume dan aktivitas pasar yang sebenarnya tidak ada.","trading",1],["whale","Whale (paus kripto)","Whale adalah sebutan untuk individu atau entitas yang memegang aset kripto dalam jumlah sangat besar sehingga transaksinya berpotensi menggerakkan harga pasar.","trading",1],["withdrawal-whitelist","Whitelist penarikan (withdrawal whitelist)","Whitelist penarikan adalah fitur keamanan exchange yang membatasi penarikan hanya ke alamat yang sudah Anda daftarkan dan verifikasi sebelumnya.","wallets-security",1],["wrapped-token","Wrapped token (token terbungkus)","Wrapped token adalah token yang mewakili aset lain dengan perbandingan 1:1, misalnya WBTC yang mewakili BTC di Ethereum, sehingga aset itu bisa dipakai di jaringan atau aplikasi yang tidak mendukungnya secara langsung.","defi",1],["yield-farming","Yield farming","Yield farming adalah strategi menempatkan aset kripto di berbagai protokol DeFi, seperti liquidity pool atau lending, untuk mendapatkan fee, bunga, dan token insentif.","defi",1]]});
